.si-anim svg { overflow: visible; }

/* 1. LOCK-CLOSED: Deadbolt engage. Drops down with heavy metallic clunk. */
.si-icon-cell:hover .scd9j1 svg,
.icon-card:hover .scd9j1 svg {
  animation: la9td1 0.5s cubic-bezier(0.22, 1, 0.36, 1) forwards;
  transform-origin: center;
  filter: drop-shadow(0 0 4px rgba(34, 197, 94, 0.3));
}

/* 2. LOCK-OPEN: Shackle release. Pops upward with spring energy. */
.si-icon-cell:hover .fdf3sg svg,
.icon-card:hover .fdf3sg svg {
  animation: pshqwl 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
  transform-origin: center bottom;
  filter: drop-shadow(0 0 4px rgba(251, 191, 36, 0.3));
}

/* 3. KEY-TURN: Tumbler rotation. Rotates like a key turning in a lock cylinder. */
.si-icon-cell:hover .i6bk27 svg,
.icon-card:hover .i6bk27 svg {
  animation: plaq2u 0.6s cubic-bezier(0.22, 1, 0.36, 1) forwards;
  transform-origin: left center;
  filter: drop-shadow(0 0 4px rgba(251, 191, 36, 0.3));
}

