}

/* 29. SECURITY-UPDATE: Shield refresh. Rotates with an ascending glow like updating defenses. */
.si-icon-cell:hover .wosk5y svg,
.icon-card:hover .wosk5y svg {
  animation: rkk4ni 0.6s cubic-bezier(0.22, 1, 0.36, 1) forwards;
  transform-origin: center;
}

/* 30. NO-ENCRYPTION: Crack shatter. Icon fractures with jitter like broken encryption. */
.si-icon-cell:hover .mfx3jq svg,
.icon-card:hover .mfx3jq svg {
  animation: mj2bi3 0.5s ease forwards;
  transform-origin: center;
}

/* 31. POLICY: Scroll unfurl. Unrolls vertically from top like an ancient decree. */
.si-icon-cell:hover .dntd3p svg,
.icon-card:hover .dntd3p svg {
  animation: b1rdb9 0.6s cubic-bezier(0.22, 1, 0.36, 1) forwards;
  transform-origin: center top;
}

/* 32. SAFETY-CHECK: Heartbeat vital. Double-pulse like a vitals monitor confirming safety. */
.si-icon-cell:hover .jpc3xs svg,
.icon-card:hover .jpc3xs svg {
  animation: gz1tgp 0.6s ease forwards;
  transform-origin: center;
  filter: drop-shadow(0 0 4px rgba(34, 197, 94, 0.3));
}

/* 33. GPP-GOOD: Green fortress. Expands outward with radiating green shield energy. */
.si-icon-cell:hover .ysxs5e svg,
.icon-card:hover .ysxs5e svg {
  animation: cqty0x 0.55s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
  transform-origin: center;
}

/* 34. GPP-BAD: Red breach. Trembles with escalating red pulse like perimeter failing. */
.si-icon-cell:hover .wd42q3 svg,
.icon-card:hover .wd42q3 svg {
  animation: zxdw62 0.5s ease forwards;
  transform-origin: center;
}

/* 35. GPP-MAYBE: Amber caution. Wobbles side-to-side with amber glow like uncertain status. */
.si-icon-cell:hover .wdzr3e svg,
.icon-card:hover .wdzr3e svg {
  animation: in50it 0.55s ease forwards;
  transform-origin: center bottom;
}

/* 36. MONITORING: Surveillance pan. Camera pans left-to-right with lens focus pulses
       at key positions, infrared glow traces the sweep path. */
.si-icon-cell:hover .r3kp6x svg,
.icon-card:hover .r3kp6x svg {
  animation: dlx290 0.8s cubic-bezier(0.22, 1, 0.36, 1) forwards;
  transform-origin: center;
}

/* 37. EMERGENCY-SHARE: SOS beacon. Rapid triple-flash like an emergency distress signal. */
.si-icon-cell:hover .ff7jvu svg,
.icon-card:hover .ff7jvu svg {
  animation: ylcx96 0.6s ease forwards;
  transform-origin: center;
}

/* 38. REPORT-FLAG: Flag plant. Drives downward into ground then stands upright with authority. */
.si-icon-cell:hover .u4qwkq svg,
.icon-card:hover .u4qwkq svg {
  animation: e1abh2 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
  transform-origin: center bottom;
}

/* 39. DOOR-LOCK: Bolt slide. Horizontal bolt slides across like a deadbolt engaging. */
.si-icon-cell:hover .xj3ydo svg,
.icon-card:hover .xj3ydo svg {
  animation: j4lug2 0.45s cubic-bezier(0.22, 1, 0.36, 1) forwards;
  transform-origin: center;
}

/* 40. MEETING-ROOM: Access granted. Pulses with welcome green then settles. */
.si-icon-cell:hover .f1u24y svg,
.icon-card:hover .f1u24y svg {
  animation: gyz9o3 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
  transform-origin: center;
}

/* 41. DEVICE-TRUST: Multi-device sync. Cascading scale pulses like trust propagating across devices. */
.si-icon-cell:hover .vmqzn3 svg,
.icon-card:hover .vmqzn3 svg {
  animation: d8ju5g 0.6s ease forwards;
  transform-origin: center;
}

/* 42. PHONE-LOCK: Screen lock. 3D folds closed on Y-axis like a phone screen locking. */
.si-icon-cell:hover .t3vi7w svg,
.icon-card:hover .t3vi7w svg {
  animation: x2gqlz 0.55s cubic-bezier(0.22, 1, 0.36, 1) forwards;
  transform-origin: center;
}

/* 43. LAPTOP-SECURE: Lid close. 3D rotateX folds top-down like closing a laptop lid. */
.si-icon-cell:hover .vxld77 svg,
.icon-card:hover .vxld77 svg {
  animation: hykb3x 0.55s cubic-bezier(0.22, 1, 0.36, 1) forwards;
  transform-origin: center bottom;
}

/* 44. DESKTOP-ACCESS: Monitor wake. Brightens from dark with slight scale like a monitor powering on. */
.si-icon-cell:hover .p40xmt svg,
.icon-card:hover .p40xmt svg {
  animation: i8f2rz 0.55s cubic-bezier(0.22, 1, 0.36, 1) forwards;
  transform-origin: center;
}

/* 45. DNS-SECURITY: Resolve cascade. Steps through nodes like DNS resolution chain. */
.si-icon-cell:hover .p515sh svg,
.icon-card:hover .p515sh svg {
  animation: xo85z5 0.65s steps(4, end) forwards;
  transform-origin: center;
}

/* 46. NETWORK-NODE: Signal broadcast. Pulses outward with concentric rings like a router broadcasting. */
.si-icon-cell:hover .j5rd9z svg,
.icon-card:hover .j5rd9z svg {
  animation: rkt7cx 0.6s ease forwards;
  transform-origin: center;
}

/* 47. CLOUD-DONE: Data uplift. Rises from ground with transfer blur,
       solidifies at cloud altitude with 3D green checkmark radiance. */
.si-icon-cell:hover .ywdkmn svg,
.icon-card:hover .ywdkmn svg {
  animation: kzua0i 0.7s cubic-bezier(0.22, 1, 0.36, 1) forwards;
  transform-origin: center bottom;
}

/* 48. API-KEY: Bracket snap. Angle brackets contract inward then snap out with glow. */
.si-icon-cell:hover .tpwnmb svg,
.icon-card:hover .tpwnmb svg {
  animation: hg3syl 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
  transform-origin: center;
}

/* 49. TERMINAL-ACCESS: Cursor blink. Flashes with a command-line cursor rhythm. */
.si-icon-cell:hover .d2l01n svg,
.icon-card:hover .d2l01n svg {
  animation: gm0lbh 0.6s steps(4, end) forwards;
  transform-origin: center;
}

/* 50. DATA-GUARD: Vault lock. 3D perspective closes with heavy mechanical feel. */
.si-icon-cell:hover .wa7g98 svg,
.icon-card:hover .wa7g98 svg {
  animation: qt1ptr 0.6s cubic-bezier(0.22, 1, 0.36, 1) forwards;
  transform-origin: center;
}

/* ===================== KEYFRAMES ===================== */

/* 1. Deadbolt close: heavy metallic drop and lock */
@keyframes la9td1 {
  0%   { transform: translateY(-6px) rotate(-3deg); filter: brightness(1); }
  30%  { transform: translateY(0) rotate(0deg); }
  45%  { transform: translateY(2px) scaleY(0.95) scaleX(1.05); filter: brightness(1.3) drop-shadow(0 0 6px rgba(34,197,94,0.4)); }
  60%  { transform: translateY(-1px) scaleY(1.02); }
  100% { transform: translateY(0) scaleY(1) scaleX(1) rotate(0deg); filter: brightness(1); }
}

/* 2. Shackle release: spring pop upward */
@keyframes pshqwl {
  0%   { transform: translateY(0) scaleY(1); }
  20%  { transform: translateY(2px) scaleY(0.92); }
  45%  { transform: translateY(-8px) scaleY(1.08); filter: brightness(1.3) drop-shadow(0 0 6px rgba(251,191,36,0.4)); }
  65%  { transform: translateY(-3px) scaleY(1.02); filter: brightness(1.1); }
  85%  { transform: translateY(1px) scaleY(0.99); }
  100% { transform: translateY(0) scaleY(1); filter: brightness(1); }
}

/* 3. Tumbler turn: key rotates in cylinder */
@keyframes plaq2u {
  0%   { transform: rotate(0deg); filter: brightness(1); }
  25%  { transform: rotate(-30deg); filter: brightness(1.1); }
  50%  { transform: rotate(-45deg); filter: brightness(1.4) drop-shadow(0 0 6px rgba(251,191,36,0.3)); }
  70%  { transform: rotate(-35deg); filter: brightness(1.15); }
  85%  { transform: rotate(-42deg); }
  100% { transform: rotate(0deg); filter: brightness(1); }
}

/* 4. Deflection pulse: shield absorbs then radiates */
@keyframes hiupw6 {
  0%   { transform: perspective(200px) translateZ(0) scale(1); filter: brightness(1) drop-shadow(0 0 0 transparent); }
  15%  { transform: perspective(200px) translateZ(-5px) scale(0.92); filter: brightness(0.8); }
  35%  { transform: perspective(200px) translateZ(15px) scale(1.08); filter: brightness(1.5) drop-shadow(0 0 10px rgba(34,197,94,0.5)); }
  55%  { transform: perspective(200px) translateZ(5px) scale(1.03); filter: brightness(1.2) drop-shadow(0 0 6px rgba(34,197,94,0.3)); }
  100% { transform: perspective(200px) translateZ(0) scale(1); filter: brightness(1) drop-shadow(0 0 0 transparent); }
}

/* 5. Ridge illuminate: 3D tilt + concentric ring glow + access flash */
@keyframes l567tq {
  0%   { transform: perspective(250px) rotateX(0deg) rotateY(0deg) scale(1); filter: brightness(1) drop-shadow(0 0 0 transparent); }
  12%  { transform: perspective(250px) rotateX(12deg) rotateY(-5deg) scale(1.02); filter: brightness(1.15) drop-shadow(0 0 3px rgba(34,197,94,0.15)); }
  25%  { transform: perspective(250px) rotateX(18deg) rotateY(-8deg) scale(1.04); filter: brightness(1.3) drop-shadow(0 0 6px rgba(34,197,94,0.3)); }
  38%  { transform: perspective(250px) rotateX(20deg) rotateY(-6deg) scale(1.05); filter: brightness(1.5) drop-shadow(0 0 10px rgba(34,197,94,0.45)); }
  50%  { transform: perspective(250px) rotateX(18deg) rotateY(-3deg) scale(1.06); filter: brightness(1.7) drop-shadow(0 0 14px rgba(34,197,94,0.55)); }
  62%  { transform: perspective(250px) rotateX(12deg) rotateY(0deg) scale(1.08); filter: brightness(2.2) drop-shadow(0 0 18px rgba(34,197,94,0.7)); }
  72%  { transform: perspective(250px) rotateX(5deg) rotateY(2deg) scale(1.04); filter: brightness(1.4) drop-shadow(0 0 10px rgba(34,197,94,0.35)); }
  85%  { transform: perspective(250px) rotateX(2deg) rotateY(1deg) scale(1.02); filter: brightness(1.15) drop-shadow(0 0 4px rgba(34,197,94,0.15)); }
  100% { transform: perspective(250px) rotateX(0deg) rotateY(0deg) scale(1); filter: brightness(1) drop-shadow(0 0 0 transparent); }
}

/* 6. Face recognition: contracts to focus point then confirms */
@keyframes v2cr3f {
  0%   { transform: perspective(200px) scale(1) rotateX(0deg); filter: brightness(1); }
  20%  { transform: perspective(200px) scale(0.88) rotateX(5deg); filter: brightness(0.8); }
  40%  { transform: perspective(200px) scale(0.85) rotateX(8deg); filter: brightness(0.7) drop-shadow(0 0 4px rgba(96,165,250,0.3)); }
  55%  { transform: perspective(200px) scale(1.06) rotateX(-2deg); filter: brightness(1.8) drop-shadow(0 0 12px rgba(34,197,94,0.5)); }
  75%  { transform: perspective(200px) scale(1.02) rotateX(0deg); filter: brightness(1.2) drop-shadow(0 0 4px rgba(34,197,94,0.2)); }
  100% { transform: perspective(200px) scale(1) rotateX(0deg); filter: brightness(1); }
}

/* 7. OTP cascade: stepped digit roll */
@keyframes eefx2x {
  0%   { transform: translateY(0); opacity: 0.7; }
  25%  { transform: translateY(-3px); opacity: 0.8; }
  50%  { transform: translateY(-6px); opacity: 0.9; }
  75%  { transform: translateY(-3px); opacity: 0.95; }
  100% { transform: translateY(0); opacity: 1; filter: brightness(1.2) drop-shadow(0 0 4px rgba(96,165,250,0.3)); }
}

/* 8. Iris dilate: eye opens wide with perspective depth */
@keyframes fau4hp {
  0%   { transform: perspective(200px) scaleX(1) scaleY(1) translateZ(0); filter: brightness(1); }
  30%  { transform: perspective(200px) scaleX(1.15) scaleY(0.9) translateZ(5px); filter: brightness(1.2); }
  50%  { transform: perspective(200px) scaleX(1.25) scaleY(1.1) translateZ(10px); filter: brightness(1.5) drop-shadow(0 0 8px rgba(139,92,246,0.4)); }
  70%  { transform: perspective(200px) scaleX(1.1) scaleY(1.02) translateZ(3px); filter: brightness(1.15); }
  100% { transform: perspective(200px) scaleX(1) scaleY(1) translateZ(0); filter: brightness(1); }
}

/* 9. Matrix scramble: rapid multi-axis rotation with blur */
@keyframes l6e3mk {
  0%   { transform: perspective(200px) rotateX(0deg) rotateY(0deg) rotateZ(0deg); filter: blur(0) brightness(1); }
  15%  { transform: perspective(200px) rotateX(15deg) rotateY(-20deg) rotateZ(5deg); filter: blur(1px) brightness(1.3); }
  30%  { transform: perspective(200px) rotateX(-10deg) rotateY(25deg) rotateZ(-8deg); filter: blur(1.5px) brightness(0.8); }
  45%  { transform: perspective(200px) rotateX(8deg) rotateY(-15deg) rotateZ(3deg); filter: blur(1px) brightness(1.5) drop-shadow(0 0 6px rgba(34,211,238,0.4)); }
  60%  { transform: perspective(200px) rotateX(-5deg) rotateY(8deg) rotateZ(-2deg); filter: blur(0.5px) brightness(1.2); }
  80%  { transform: perspective(200px) rotateX(2deg) rotateY(-3deg) rotateZ(1deg); filter: blur(0) brightness(1.05); }
  100% { transform: perspective(200px) rotateX(0deg) rotateY(0deg) rotateZ(0deg); filter: blur(0) brightness(1); }
}

/* 10. Barrier rise: scales up from base like a wall */
@keyframes qascmc {
  0%   { transform: scaleY(0.7) scaleX(0.95); filter: brightness(0.8); }
  30%  { transform: scaleY(1.05) scaleX(1); filter: brightness(1.2); }
  50%  { transform: scaleY(1.1) scaleX(1.02); filter: brightness(1.4) drop-shadow(0 0 8px rgba(239,68,68,0.4)); }
  70%  { transform: scaleY(1.02) scaleX(1); filter: brightness(1.1); }
  100% { transform: scaleY(1) scaleX(1); filter: brightness(1); }
}

/* 11. Tunnel depth: pulls inward with perspective */
@keyframes gr8cxx {
